import {controlProject} from './recording-control-project.mjs';
export function overdubProject(){const project=controlProject();project.name='Overdub-Proof';project.clips.loop={id:'loop',kind:'midi',name:'Existing Loop',sourceBpm:120,beats:2,notes:[{pitch:48,start:0,duration:.15,velocity:.4,releaseVelocity:.2},{pitch:55,start:1,duration:.1,velocity:.5}]};project.tracks[0].slots[0]='loop';return project;}
